def master_rows() -> list[list[str]]:
    return list(csv.reader(io.StringIO(MASTER)))


def test_fixtures_are_the_recorded_shapes():
    assert MASTER.startswith('"Token"') and len(master_rows()) == 13
    assert TICKS["TATASTEEL"]["symbol"] == "4.1!3499" and TICKS["NIFTY 50"]["symbol"] == "4.1!NIFTY 50"
    assert TICKS["NIFTY 50"]["bPrice"] == "" and TICKS["NIFTY 50"]["ttq"] == ""     # index ticks: empty book / volume
    assert {r["symbol"] for r in HEATMAP} >= {"HDFCBANK", "RELIANCE"} and ALL_INDICES["timestamp"] == "05-Nov-2026 10:13"
    assert NEXTAPI["equityResponse"][0]["lastUpdateTime"] == "05-Nov-2026 10:15:53"
